import React, { useEffect, useState } from 'react';
import { Button, Input, Select, dispatchAppToast } from '@linm-soft-org/linm-web-common-components';
import { useParams, useSearchParams } from 'react-router-dom';
import { DocumentFormHeader } from '../../../components/layout/DocumentFormHeader';
import { UnsavedChangesModal } from '../../../components/form';
import { useUnsavedChangesGuard } from '../../../hooks/useUnsavedChangesGuard';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import {
  createFinancialPlan,
  getFinancialPlan,
  updateFinancialPlan,
  type FinancialPlanWrite,
  type FinancialPlanWriteLine,
} from '../../../services/kt/financialPlans';
import df from '../../../styles/documentForm.module.css';

interface LineState {
  sttRec0: string;
  tkNo: string;
  tkCo: string;
  maTd5I: string;
  psNt: string;
  dienGiaii: string;
  ps: number | null;
}

interface FormState {
  maGd: string;
  maPost: string;
  ngayCt: string;
  ngayLct: string;
  soCt: string;
  thang: string;
  nam: string;
  ngayKh1: string;
  ngayKh2: string;
  maKh: string;
  maBpH: string;
  maHsH: string;
  ongBa: string;
  diaChi: string;
  dienGiai: string;
  maNt: string;
  tyGia: string;
  lines: LineState[];
}

const emptyLine = (): LineState => ({
  sttRec0: '',
  tkNo: '',
  tkCo: '',
  maTd5I: '',
  psNt: '',
  dienGiaii: '',
  ps: null,
});

function today(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function createDefault(): FormState {
  const date = today();
  return {
    maGd: '2',
    maPost: '3',
    ngayCt: date,
    ngayLct: date,
    soCt: '',
    thang: '',
    nam: '',
    ngayKh1: '',
    ngayKh2: '',
    maKh: '',
    maBpH: '',
    maHsH: '',
    ongBa: '',
    diaChi: '',
    dienGiai: '',
    maNt: 'VND',
    tyGia: '',
    lines: [],
  };
}

function dateOrEmpty(value: string | null | undefined): string {
  return value ? value.slice(0, 10) : '';
}

function nullText(value: string): string | null {
  const text = value.trim();
  return text ? text : null;
}

function nullNumber(value: string): number | null {
  const text = value.trim();
  if (!text) return null;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : null;
}

function integerInRange(raw: string, min: number, max: number): number | null {
  const text = raw.trim();
  if (!/^\d+$/.test(text)) return null;
  const value = Number(text);
  if (!Number.isInteger(value) || value < min || value > max) return null;
  return value;
}

function validateClient(form: FormState): string | null {
  const thang = integerInRange(form.thang, 1, 12);
  const nam = integerInRange(form.nam, 1, 99999);
  if (thang == null || nam == null) return 'Bạn chưa nhập tháng, năm kế hoạch';
  if (form.ngayKh1.trim() && form.ngayKh2.trim() && form.ngayKh1.trim() > form.ngayKh2.trim()) {
    return 'Ngày kế hoạch bắt đầu lớn hơn ngày kết thúc, kiểm tra lại';
  }
  return null;
}

function toLine(line: LineState, mode: 'create' | 'copy' | 'edit'): FinancialPlanWriteLine {
  const base: FinancialPlanWriteLine = {
    tkNo: nullText(line.tkNo),
    tkCo: nullText(line.tkCo),
    maTd5I: nullText(line.maTd5I),
    psNt: nullNumber(line.psNt),
    dienGiaii: nullText(line.dienGiaii),
  };
  if (mode === 'copy') {
    base.ps = line.ps == null ? 0 : line.ps;
    return base;
  }
  if (mode === 'edit' && line.ps != null && line.sttRec0.trim()) {
    base.sttRec0 = line.sttRec0.trim();
  }
  return base;
}

function toWrite(form: FormState, mode: 'create' | 'copy' | 'edit'): FinancialPlanWrite {
  const thang = integerInRange(form.thang, 1, 12) ?? 0;
  const nam = integerInRange(form.nam, 1, 99999) ?? 0;
  return {
    maGd: form.maGd,
    maPost: form.maPost,
    maCt: 'KH9',
    ngayCt: nullText(form.ngayCt),
    ngayLct: nullText(form.ngayLct),
    soCt: nullText(form.soCt),
    thang,
    nam,
    ngayKh1: nullText(form.ngayKh1),
    ngayKh2: nullText(form.ngayKh2),
    maKh: nullText(form.maKh),
    maBpH: nullText(form.maBpH),
    maHsH: nullText(form.maHsH),
    ongBa: nullText(form.ongBa),
    diaChi: nullText(form.diaChi),
    dienGiai: nullText(form.dienGiai),
    maNt: nullText(form.maNt),
    tyGia: nullNumber(form.tyGia),
    lines: form.lines.map(line => toLine(line, mode)),
  };
}

const Kh9FormPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const { sttRec: routeSttRec } = useParams();
  const [searchParams] = useSearchParams();
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = searchParams.get('mode') === 'view';
  const isNewRoute = !routeSttRec;
  const isCopy = isNewRoute && copyFrom.length > 0;
  const isCreate = isNewRoute && !isCopy;
  const isEdit = !isNewRoute && !isView;

  const [form, setForm] = useState<FormState>(createDefault);
  const [loading, setLoading] = useState(!isCreate);
  const [loadError, setLoadError] = useState('');
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);
  const [selectedLineIndex, setSelectedLineIndex] = useState<number | null>(null);
  const [isDirty, setIsDirty] = useState(false);

  const { showUnsavedModal, guardedAction, confirmLeave, cancelLeave } = useUnsavedChangesGuard(isDirty, !isView);

  useEffect(() => {
    if (isCreate) {
      setForm(createDefault());
      setIsDirty(false);
      setLoading(false);
      setLoadError('');
      return;
    }

    const key = isCopy ? copyFrom : (routeSttRec ?? '');
    let cancelled = false;
    setLoading(true);
    setLoadError('');
    void getFinancialPlan(key)
      .then(detail => {
        if (cancelled) return;
        setForm({
          maGd: detail.maGd === '4' ? '4' : '2',
          maPost: detail.maPost === '9' ? '9' : '3',
          ngayCt: dateOrEmpty(detail.ngayCt),
          ngayLct: dateOrEmpty(detail.ngayLct),
          soCt: detail.soCt ?? '',
          thang: String(detail.thang ?? ''),
          nam: String(detail.nam ?? ''),
          ngayKh1: dateOrEmpty(detail.ngayKh1),
          ngayKh2: dateOrEmpty(detail.ngayKh2),
          maKh: detail.maKh ?? '',
          maBpH: detail.maBpH ?? '',
          maHsH: detail.maHsH ?? '',
          ongBa: detail.ongBa ?? '',
          diaChi: detail.diaChi ?? '',
          dienGiai: detail.dienGiai ?? '',
          maNt: detail.maNt ?? '',
          tyGia: detail.tyGia == null ? '' : String(detail.tyGia),
          lines: (detail.lines ?? []).map(line => ({
            sttRec0: isCopy ? '' : (line.sttRec0 ?? ''),
            tkNo: line.tkNo ?? '',
            tkCo: line.tkCo ?? '',
            maTd5I: line.maTd5I ?? '',
            psNt: line.psNt == null ? '' : String(line.psNt),
            dienGiaii: line.dienGiaii ?? '',
            ps: line.ps == null ? 0 : line.ps,
          })),
        });
        setIsDirty(false);
      })
      .catch(err => {
        if (cancelled) return;
        setLoadError(getApiErrorMessage(err, 'Không tìm thấy kế hoạch tài chính'));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [isCreate, isCopy, copyFrom, routeSttRec]);

  const markDirty = () => {
    if (!isView) setIsDirty(true);
  };

  const patch = (partial: Partial<FormState>) => {
    setForm(prev => ({ ...prev, ...partial }));
    markDirty();
  };

  const patchLine = (index: number, key: keyof LineState, value: string) => {
    setForm(prev => ({
      ...prev,
      lines: prev.lines.map((line, i) => (i === index ? { ...line, [key]: value } : line)),
    }));
    markDirty();
  };

  const addLine = () => {
    setForm(prev => ({ ...prev, lines: [...prev.lines, emptyLine()] }));
    setSelectedLineIndex(form.lines.length);
    markDirty();
  };

  const removeLine = () => {
    if (selectedLineIndex == null) return;
    setForm(prev => ({ ...prev, lines: prev.lines.filter((_, i) => i !== selectedLineIndex) }));
    setSelectedLineIndex(null);
    markDirty();
  };

  const onSave = async () => {
    setSaving(true);
    setError('');
    try {
      const blocked = validateClient(form);
      if (blocked) {
        setError(blocked);
        dispatchAppToast(dispatch, { type: 'error', message: blocked });
        return;
      }
      const mode = isCopy ? 'copy' : isEdit ? 'edit' : 'create';
      const body = toWrite(form, mode);
      const saved = mode === 'edit'
        ? await updateFinancialPlan(routeSttRec as string, body)
        : await createFinancialPlan(body);
      setIsDirty(false);
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu kế hoạch tài chính' });
      navigate(`/kt/kh9/${saved.sttRec}`);
    } catch (err) {
      const message = getApiErrorMessage(err, 'Lưu thất bại');
      setError(message);
      dispatchAppToast(dispatch, { type: 'error', message });
    } finally {
      setSaving(false);
    }
  };

  const title = isView
    ? 'Xem kế hoạch tài chính'
    : isEdit
      ? 'Sửa kế hoạch tài chính'
      : 'Thêm kế hoạch tài chính';
  const locked = isView;
  const showGrid = !loadError;

  return (
    <div className={df.page} data-testid="ct-kh9-form">
      <DocumentFormHeader
        testIdPrefix="ct-kh9"
        title={title}
        isNew={isCreate || isCopy}
        isReadOnly={isView}
        saving={saving}
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        onBack={() => guardedAction(() => navigate('/kt/kh9'))}
        onSave={showGrid && !isView ? () => { void onSave(); } : undefined}
      />
      {loading ? <div className={df.loading}>Đang tải...</div> : null}
      {loadError ? <div className={df.errorBanner}>{loadError}</div> : null}
      {error ? <div className={df.errorBanner}>{error}</div> : null}
      {showGrid && !loading ? (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <Select
                label="Loại giao dịch"
                data-testid="ct-kh9-field-maGd"
                value={form.maGd}
                disabled={locked}
                options={[
                  { value: '2', label: 'KH chi phí' },
                  { value: '4', label: 'KH doanh thu' },
                ]}
                onChange={event => patch({ maGd: event.target.value })}
              />
              <Select
                label="Trạng thái"
                data-testid="ct-kh9-field-maPost"
                value={form.maPost}
                disabled={locked}
                options={[
                  { value: '3', label: 'Lập kế hoạch' },
                  { value: '9', label: 'Kế hoạch đã phê duyệt' },
                ]}
                onChange={event => patch({ maPost: event.target.value })}
              />
              <DateField label="Ngày chứng từ" testId="ct-kh9-field-ngayCt" value={form.ngayCt} disabled={locked} onChange={value => patch({ ngayCt: value })} />
              <DateField label="Ngày lập chứng từ" testId="ct-kh9-field-ngayLct" value={form.ngayLct} disabled={locked} onChange={value => patch({ ngayLct: value })} />
              <TextField label="Số kế hoạch" testId="ct-kh9-field-soCt" value={form.soCt} maxLength={30} disabled={locked} onChange={value => patch({ soCt: value })} />
              <TextField label="Tháng" testId="ct-kh9-field-thang" value={form.thang} inputMode="numeric" disabled={locked} onChange={value => patch({ thang: value })} />
              <TextField label="Năm" testId="ct-kh9-field-nam" value={form.nam} inputMode="numeric" disabled={locked} onChange={value => patch({ nam: value })} />
              <DateField label="Kế hoạch từ ngày" testId="ct-kh9-field-ngayKh1" value={form.ngayKh1} disabled={locked} onChange={value => patch({ ngayKh1: value })} />
              <DateField label="Kế hoạch đến ngày" testId="ct-kh9-field-ngayKh2" value={form.ngayKh2} disabled={locked} onChange={value => patch({ ngayKh2: value })} />
              <TextField label="Đối tượng" testId="ct-kh9-field-maKh" value={form.maKh} maxLength={30} disabled={locked} onChange={value => patch({ maKh: value })} />
              <TextField label="Bộ phận" testId="ct-kh9-field-maBpH" value={form.maBpH} maxLength={30} disabled={locked} onChange={value => patch({ maBpH: value })} />
              <TextField label="Nhân sự" testId="ct-kh9-field-maHsH" value={form.maHsH} maxLength={30} disabled={locked} onChange={value => patch({ maHsH: value })} />
              <TextField label="Người giao dịch" testId="ct-kh9-field-ongBa" value={form.ongBa} maxLength={200} disabled={locked} onChange={value => patch({ ongBa: value })} />
              <div className={df.spanCol2}>
                <TextField label="Địa chỉ" testId="ct-kh9-field-diaChi" value={form.diaChi} maxLength={200} disabled={locked} onChange={value => patch({ diaChi: value })} />
              </div>
              <div className={df.spanCol2}>
                <TextField label="Diễn giải" testId="ct-kh9-field-dienGiai" value={form.dienGiai} maxLength={200} disabled={locked} onChange={value => patch({ dienGiai: value })} />
              </div>
              <TextField label="Ngoại tệ" testId="ct-kh9-field-maNt" value={form.maNt} maxLength={3} disabled={locked} onChange={value => patch({ maNt: value })} />
              <TextField label="Tỷ giá" testId="ct-kh9-field-tyGia" value={form.tyGia} inputMode="decimal" disabled={locked} onChange={value => patch({ tyGia: value })} />
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng kế hoạch</h2>
            {!locked ? (
              <div>
                <Button variant="secondary" className={df.btnAddLine} data-testid="ct-kh9-line-add-btn" onClick={addLine}>Thêm dòng</Button>
                <Button variant="secondary" className={df.btnDeleteLine} data-testid="ct-kh9-line-remove-btn" disabled={selectedLineIndex == null} onClick={removeLine}>Xóa dòng</Button>
              </div>
            ) : null}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-kh9-line-grid">
                <thead>
                  <tr>
                    <th>Tk nợ</th>
                    <th>Tk có</th>
                    <th>Mã N.Sách</th>
                    <th>Phát sinh</th>
                    <th>Diễn giải</th>
                    <th>Phát sinh VNĐ</th>
                  </tr>
                </thead>
                <tbody>
                  {form.lines.map((line, index) => (
                    <tr
                      key={`${line.sttRec0}-${index}`}
                      aria-selected={selectedLineIndex === index}
                      style={selectedLineIndex === index ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                      onClick={() => setSelectedLineIndex(index)}
                    >
                      <LineCell index={index} field="tkNo" value={line.tkNo} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="tkCo" value={line.tkCo} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="maTd5I" value={line.maTd5I} maxLength={30} disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="psNt" value={line.psNt} inputMode="decimal" disabled={locked} onChange={patchLine} />
                      <LineCell index={index} field="dienGiaii" value={line.dienGiaii} maxLength={200} disabled={locked} onChange={patchLine} />
                      <td>
                        <Input
                          data-testid={`ct-kh9-line-${index}-ps`}
                          value={line.ps == null ? '0' : String(line.ps)}
                          inputMode="decimal"
                          disabled
                          onClick={event => event.stopPropagation()}
                        />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        </>
      ) : null}
      <UnsavedChangesModal
        isOpen={showUnsavedModal}
        onStay={cancelLeave}
        onLeave={confirmLeave}
        data-testid="ct-kh9-unsaved-modal"
      />
    </div>
  );
};

const TextField: React.FC<{
  label: string;
  testId: string;
  value: string;
  disabled: boolean;
  maxLength?: number;
  inputMode?: 'decimal' | 'numeric';
  onChange: (value: string) => void;
}> = ({ label, testId, value, disabled, maxLength, inputMode, onChange }) => (
  <div>
    <label className={df.label}>{label}</label>
    <Input
      data-testid={testId}
      value={value}
      maxLength={maxLength}
      inputMode={inputMode}
      disabled={disabled}
      onChange={event => onChange(event.target.value)}
    />
  </div>
);

const DateField: React.FC<{
  label: string;
  testId: string;
  value: string;
  disabled: boolean;
  onChange: (value: string) => void;
}> = ({ label, testId, value, disabled, onChange }) => (
  <div>
    <label className={df.label}>{label}</label>
    <Input type="date" data-testid={testId} value={value} disabled={disabled} onChange={event => onChange(event.target.value)} />
  </div>
);

const LineCell: React.FC<{
  index: number;
  field: 'tkNo' | 'tkCo' | 'maTd5I' | 'psNt' | 'dienGiaii';
  value: string;
  disabled: boolean;
  maxLength?: number;
  inputMode?: 'decimal';
  onChange: (index: number, field: keyof LineState, value: string) => void;
}> = ({ index, field, value, disabled, maxLength, inputMode, onChange }) => (
  <td>
    <Input
      data-testid={`ct-kh9-line-${index}-${field}`}
      value={value}
      disabled={disabled}
      maxLength={maxLength}
      inputMode={inputMode}
      onChange={event => onChange(index, field, event.target.value)}
      onClick={event => event.stopPropagation()}
    />
  </td>
);

export default Kh9FormPage;
